// 1. Get the JSON payload from the AI Agent node
let inputData = $input.first().json;

// 2. Extract the LLM text output
let rawText = inputData.output;

if (!rawText) {
    throw new Error("Could not find the LLM output. Expected key 'output'.");
}

let parsedJSON;
try {
    // 3. Strip markdown formatting (the ```json and ``` that Mistral might add)
    if (typeof rawText === 'string') {
        let cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
        parsedJSON = JSON.parse(cleanText);
    } else {
        parsedJSON = rawText; 
    }
} catch (error) {
    throw new Error("Failed to parse JSON. Mistral output was: " + rawText);
}

// 4. Handle different structures the LLM might return
let itemsArray = [];

if (Array.isArray(parsedJSON)) {
    // Case A: The LLM returned a JSON array directly: [ { summary: "...", ... } ]
    itemsArray = parsedJSON;
} else if (parsedJSON && parsedJSON.news_items && Array.isArray(parsedJSON.news_items)) {
    // Case B: The LLM returned an object with the key 'news_items'
    itemsArray = parsedJSON.news_items;
} else {
    // Case C: The structure is entirely unexpected.
    // Throw an error that prints the actual parsed JSON so you can see what went wrong.
    throw new Error("Unexpected JSON structure. Received: " + JSON.stringify(parsedJSON));
}

// 5. Return the array in n8n's expected item format.
// Carry the station id AND the source audio clip reference from the
// original webhook trigger along on every split news item, so they survive
// through the If/AI Agent1 branch and can be re-attached to the final
// payload in "Code in JavaScript1". The clip lets the dashboard play back
// the actual moment a claim was said, not just show the transcribed text.
const webhookBody = $('Webhook').first().json.body;
const station = webhookBody.station;
const audioClipId = webhookBody.audio_clip_id;
const audioHighlightStart = webhookBody.audio_clip_highlight_start;
const audioHighlightEnd = webhookBody.audio_clip_highlight_end;

return itemsArray.map(item => {
    return {
        json: {
            summary: item.summary || "",
            category: item.category || "",
            needs_fact_check: typeof item.needs_fact_check === 'boolean'
                ? item.needs_fact_check
                : typeof item.needs_fact_check === 'string'
                    ? item.needs_fact_check.trim().toLowerCase() === 'true'
                    : null,
            reasoning: item.reasoning || "",
            station: station,
            audio_clip_id: audioClipId,
            audio_clip_highlight_start: audioHighlightStart,
            audio_clip_highlight_end: audioHighlightEnd
        }
    };
});

// 1. Get the raw, mangled string from Mistral
const item = $input.first().json;
let rawText = item.output || item.text || item.message || item.content || item.response || "";

// 2. Extract ONLY the JSON part (ignoring conversational text like "Voici l'analyse...")
const jsonMatch = rawText.match(/({[\s\S]*})/);
if (!jsonMatch) {
    throw new Error("No JSON object found in output. Raw text: " + rawText);
}
let jsonString = jsonMatch[1];

// 3. SURGICAL CLEANING: We must remove newlines that break JSON structure, 
//    but preserve the "\n" characters inside string values.

// A. Temporarily protect valid paragraph breaks (e.g. \\n) by swapping them
jsonString = jsonString.replace(/\\\\n/g, '@@PARAGRAPH@@');

// B. Convert any remaining single backslash-n to protected paragraphs
jsonString = jsonString.replace(/\\n/g, '@@PARAGRAPH@@');

// C. Now, destroy ALL physical line breaks and extra spaces that break JSON keys
jsonString = jsonString.replace(/[\r\n]+/g, '');

// D. Restore the protected paragraph breaks
jsonString = jsonString.replace(/@@PARAGRAPH@@/g, '\\n');

// 4. Parse the cleaned string
let parsedData;
try {
    parsedData = JSON.parse(jsonString);
} catch (e) {
    throw new Error("Failed to parse JSON even after cleaning: " + e.message + " | Attempted string: " + jsonString);
}

// 5. Re-attach the station id and audio clip reference (carried through
// from the original webhook by the earlier "Code in JavaScript" node) so
// the dashboard can group this fact-check under the right radio station's
// page and play back the moment the claim was made.
const webhookBody = $('Webhook').first().json.body;
parsedData.station = webhookBody.station;
parsedData.audio_clip_id = webhookBody.audio_clip_id;
parsedData.audio_clip_highlight_start = webhookBody.audio_clip_highlight_start;
parsedData.audio_clip_highlight_end = webhookBody.audio_clip_highlight_end;

// 6. Return it securely as a stringified payload for Next.js
return [{
    json: {
        body_payload: JSON.stringify(parsedData)
    }
}];
